<template> <ion-page> <ion-header> <ion-toolbar> <ion-buttons slot="start"> <ion-back-button default-href="/settings"></ion-back-button> </ion-buttons> <ion-title>Developer Options</ion-title> </ion-toolbar> </ion-header> <ion-content :fullscreen="true"> <ion-list> <ion-item> <ion-label>Debug Mode</ion-label> <ion-toggle v-model="developer.debugMode" @ionChange="updateDeveloper"></ion-toggle> </ion-item> <ion-item button @click="exportLogs"> <ion-label>Export Logs</ion-label> </ion-item> </ion-list> <ion-toast :is-open="toast.isOpen" :message="toast.message" :duration="2000" @didDismiss="toast.isOpen = false" ></ion-toast> </ion-content> </ion-page> </template> <script lang="ts"> import { defineComponent, ref, onMounted } from 'vue'; import { IonPage, IonHeader, IonToolbar, IonButtons, IonBackButton, IonTitle, IonContent, IonList, IonItem, IonLabel, IonToggle, IonToast } from '@ionic/vue'; import api from '../services/api'; import { DeveloperOptions } from '../types/settings'; export default defineComponent({ name: 'DeveloperOptions', components: { IonPage, IonHeader, IonToolbar, IonButtons, IonBackButton, IonTitle, IonContent, IonList, IonItem, IonLabel, IonToggle, IonToast }, setup() { const developer = ref<DeveloperOptions>({ debugMode: false }); const toast = ref({ isOpen: false, message: '' }); const fetchDeveloper = async () => { try { const response = await api.get('/user/developer'); developer.value = response.data; } catch (error) { toast.value = { isOpen: true, message: 'Failed to load developer options' }; } }; const updateDeveloper = async () => { try { await api.post('/user/developer', developer.value); toast.value = { isOpen: true, message: 'Developer options updated' }; } catch (error) { toast.value = { isOpen: true, message: 'Failed to update developer options' }; } }; const exportLogs = async () => { try { const response = await api.get('/user/logs'); const blob = new Blob([JSON.stringify(response.data)], { type: 'application/json' }); const url = window.URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'logs.json'; a.click(); window.URL.revokeObjectURL(url); toast.value = { isOpen: true, message: 'Logs exported' }; } catch (error) { toast.value = { isOpen: true, message: 'Failed to export logs' }; } }; onMounted(fetchDeveloper); return { developer, toast, updateDeveloper, exportLogs }; }, }); </script>